import React, { useEffect, useState } from "react";
import Papa from "papaparse";
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
} from "recharts";
import { Box, Container, Grid, Typography } from "@mui/material";
import HomeHeaderNavi from './components/Nav/homepageheader';

type DataRow = {
  name: string;
  uv: number;
  pv: number;
};



const LineChartFromCSV: React.FC = () => {
  const [data, setData] = useState<DataRow[]>([]);

  useEffect(() => {
    fetch("/data.csv")
      .then((response) => response.text())
      .then((csvText) => {
        const parsed = Papa.parse(csvText, {
          header: true,
          skipEmptyLines: true,
          dynamicTyping: true,
        });
        setData(parsed.data as DataRow[]);
      });
  }, []);

  // テーブルのカラム名を取得（データが空の場合は空配列）
  const columns = data.length > 0 ? Object.keys(data[0]) : [];

  return (
    <>
      <HomeHeaderNavi/>
      <Typography variant="h5" component="div" gutterBottom
        sx={{marginTop: 5, marginBottom:3,textAlign: 'left',fontWeight:"bold"}}
      >
        今週号の作品順位
      </Typography>
      {/* テーブル表示 */}
      <table border={1} cellPadding={4} cellSpacing={0} style={{ marginBottom: 32 }} className="styled-table">
        <thead>
          <tr>
            {columns.map((col) => (
              <th key={col}>{col}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {data.map((row, idx) => (
            <tr key={idx}>
              {columns.map((col) => (
                <td key={col}>{row[col as keyof DataRow]}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
       {/* スタイル定義 */}
      <style>{`
        .styled-table {
          border-collapse: collapse;
          margin: 20px 0;
          font-size: 16px;
          min-width: 400px;
          box-shadow: 0 0 10px rgba(0,0,0,0.08);
          width: 100%;
        }
        .styled-table thead tr {
          background-color: #009879;
          color: #ffffff;
          text-align: left;
        }
        .styled-table th, .styled-table td {
          padding: 12px 15px;
          border: 1px solid #dddddd;
        }
        .styled-table tbody tr {
          border-bottom: 1px solid #dddddd;
          background-color: #f3f3f3;
        }
        .styled-table tbody tr:nth-of-type(even) {
          background-color: #e9f7f6;
        }
        .styled-table tbody tr:hover {
          background-color: #b7eadc;
        }
      `}</style>

      {/* グラフ表示 */}
      <Typography variant="h5" component="div" gutterBottom
        sx={{marginTop: 10, marginBottom:3,textAlign: 'left',fontWeight:"bold"}}
      >
        作品の掲載順位の推移
      </Typography>
      <ResponsiveContainer width="100%" height={300}>
        <LineChart data={data} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="name" />
          <YAxis />
          <Tooltip />
          <Legend />
          <Line type="monotone" dataKey="uv" stroke="#8884d8" />
          <Line type="monotone" dataKey="pv" stroke="#82ca9d" />
        </LineChart>
      </ResponsiveContainer>
    </>
  );
};

export default LineChartFromCSV;
